INSERT INTO public.translations (key, language, value, created_at, created_by, updated_at, updated_by, version) VALUES
  ('emailsender.callable.send.templateCode', 'en-GB', 'Which email template to send — pick a row from the template catalog. It is rendered with the values mapped under "variables".', now(), 'migration-callable-help', now(), 'migration-callable-help', 1),
  ('emailsender.callable.send.templateCode', 'en-US', 'Which email template to send — pick a row from the template catalog. It is rendered with the values mapped under "variables".', now(), 'migration-callable-help', now(), 'migration-callable-help', 1),
  ('emailsender.callable.send.templateCode', 'it-IT', 'Quale modello di email inviare — scegli una riga dal catalogo dei modelli. Viene composta con i valori mappati in "variables".', now(), 'migration-callable-help', now(), 'migration-callable-help', 1),
  ('emailsender.callable.send.templateCode', 'de-DE', 'Welche E-Mail-Vorlage gesendet wird — wähle eine Zeile aus dem Vorlagenkatalog. Sie wird mit den unter „variables" gemappten Werten gerendert.', now(), 'migration-callable-help', now(), 'migration-callable-help', 1),
  ('emailsender.callable.send.templateCode', 'fr-FR', 'Quel modèle d''e-mail envoyer — choisis une ligne du catalogue de modèles. Il est rendu avec les valeurs mappées sous « variables ».', now(), 'migration-callable-help', now(), 'migration-callable-help', 1),
  ('emailsender.callable.send.templateCode', 'es-ES', 'Qué plantilla de correo enviar — elige una fila del catálogo de plantillas. Se compone con los valores mapeados en «variables».', now(), 'migration-callable-help', now(), 'migration-callable-help', 1),
  ('emailsender.callable.send.templateCode', 'pt-PT', 'Que modelo de e-mail enviar — escolhe uma linha do catálogo de modelos. É composto com os valores mapeados em «variables».', now(), 'migration-callable-help', now(), 'migration-callable-help', 1),
  ('emailsender.callable.send.languageIso', 'en-GB', 'The language the email is sent in — picks which language variant of the template each recipient gets (e.g. it-IT, en-US). Uses the standard BCP-47 locale format.', now(), 'migration-callable-help', now(), 'migration-callable-help', 1),
  ('emailsender.callable.send.languageIso', 'en-US', 'The language the email is sent in — picks which language variant of the template each recipient gets (e.g. it-IT, en-US). Uses the standard BCP-47 locale format.', now(), 'migration-callable-help', now(), 'migration-callable-help', 1),
  ('emailsender.callable.send.languageIso', 'it-IT', 'La lingua in cui viene inviata l''email — sceglie quale variante linguistica del modello riceve ogni destinatario (es. it-IT, en-US). Usa il formato locale standard BCP-47.', now(), 'migration-callable-help', now(), 'migration-callable-help', 1),
  ('emailsender.callable.send.languageIso', 'de-DE', 'Die Sprache, in der die E-Mail versendet wird — bestimmt, welche Sprachvariante der Vorlage jeder Empfänger erhält (z. B. it-IT, en-US). Verwendet das Standardformat BCP-47.', now(), 'migration-callable-help', now(), 'migration-callable-help', 1),
  ('emailsender.callable.send.languageIso', 'fr-FR', 'La langue d''envoi de l''e-mail — détermine quelle variante linguistique du modèle reçoit chaque destinataire (ex. it-IT, en-US). Utilise le format de locale standard BCP-47.', now(), 'migration-callable-help', now(), 'migration-callable-help', 1),
  ('emailsender.callable.send.languageIso', 'es-ES', 'El idioma en que se envía el correo — determina qué variante lingüística de la plantilla recibe cada destinatario (p. ej. it-IT, en-US). Usa el formato de configuración regional estándar BCP-47.', now(), 'migration-callable-help', now(), 'migration-callable-help', 1),
  ('emailsender.callable.send.languageIso', 'pt-PT', 'O idioma em que o e-mail é enviado — determina qual variante linguística do modelo cada destinatário recebe (ex. it-IT, en-US). Usa o formato de localidade padrão BCP-47.', now(), 'migration-callable-help', now(), 'migration-callable-help', 1),
  ('emailsender.callable.send.to', 'en-GB', 'Who receives the email — one or more addresses. Map an event field carrying a single address or a whole list.', now(), 'migration-callable-help', now(), 'migration-callable-help', 1),
  ('emailsender.callable.send.to', 'en-US', 'Who receives the email — one or more addresses. Map an event field carrying a single address or a whole list.', now(), 'migration-callable-help', now(), 'migration-callable-help', 1),
  ('emailsender.callable.send.to', 'it-IT', 'Chi riceve l''email — uno o più indirizzi. Mappa un campo dell''evento che contiene un singolo indirizzo o un''intera lista.', now(), 'migration-callable-help', now(), 'migration-callable-help', 1),
  ('emailsender.callable.send.to', 'de-DE', 'Wer die E-Mail erhält — eine oder mehrere Adressen. Mappe ein Ereignisfeld mit einer einzelnen Adresse oder einer ganzen Liste.', now(), 'migration-callable-help', now(), 'migration-callable-help', 1),
  ('emailsender.callable.send.to', 'fr-FR', 'Qui reçoit l''e-mail — une ou plusieurs adresses. Mappe un champ de l''événement portant une seule adresse ou une liste entière.', now(), 'migration-callable-help', now(), 'migration-callable-help', 1),
  ('emailsender.callable.send.to', 'es-ES', 'Quién recibe el correo — una o más direcciones. Mapea un campo del evento que contenga una sola dirección o una lista completa.', now(), 'migration-callable-help', now(), 'migration-callable-help', 1),
  ('emailsender.callable.send.to', 'pt-PT', 'Quem recebe o e-mail — um ou mais endereços. Mapeia um campo do evento com um único endereço ou uma lista inteira.', now(), 'migration-callable-help', now(), 'migration-callable-help', 1),
  ('emailsender.callable.send.cc', 'en-GB', 'Who is copied on the email — one or more addresses, visible to every recipient.', now(), 'migration-callable-help', now(), 'migration-callable-help', 1),
  ('emailsender.callable.send.cc', 'en-US', 'Who is copied on the email — one or more addresses, visible to every recipient.', now(), 'migration-callable-help', now(), 'migration-callable-help', 1),
  ('emailsender.callable.send.cc', 'it-IT', 'Chi riceve l''email in copia — uno o più indirizzi, visibili a tutti i destinatari.', now(), 'migration-callable-help', now(), 'migration-callable-help', 1),
  ('emailsender.callable.send.cc', 'de-DE', 'Wer die E-Mail in Kopie erhält — eine oder mehrere Adressen, für alle Empfänger sichtbar.', now(), 'migration-callable-help', now(), 'migration-callable-help', 1),
  ('emailsender.callable.send.cc', 'fr-FR', 'Qui reçoit l''e-mail en copie — une ou plusieurs adresses, visibles par tous les destinataires.', now(), 'migration-callable-help', now(), 'migration-callable-help', 1),
  ('emailsender.callable.send.cc', 'es-ES', 'Quién recibe el correo en copia — una o más direcciones, visibles para todos los destinatarios.', now(), 'migration-callable-help', now(), 'migration-callable-help', 1),
  ('emailsender.callable.send.cc', 'pt-PT', 'Quem recebe o e-mail em cópia — um ou mais endereços, visíveis a todos os destinatários.', now(), 'migration-callable-help', now(), 'migration-callable-help', 1),
  ('emailsender.callable.send.bcc', 'en-GB', 'Who is silently copied on the email — one or more addresses, hidden from the other recipients.', now(), 'migration-callable-help', now(), 'migration-callable-help', 1),
  ('emailsender.callable.send.bcc', 'en-US', 'Who is silently copied on the email — one or more addresses, hidden from the other recipients.', now(), 'migration-callable-help', now(), 'migration-callable-help', 1),
  ('emailsender.callable.send.bcc', 'it-IT', 'Chi riceve l''email in copia nascosta — uno o più indirizzi, invisibili agli altri destinatari.', now(), 'migration-callable-help', now(), 'migration-callable-help', 1),
  ('emailsender.callable.send.bcc', 'de-DE', 'Wer die E-Mail in Blindkopie erhält — eine oder mehrere Adressen, für die anderen Empfänger unsichtbar.', now(), 'migration-callable-help', now(), 'migration-callable-help', 1),
  ('emailsender.callable.send.bcc', 'fr-FR', 'Qui reçoit l''e-mail en copie cachée — une ou plusieurs adresses, invisibles pour les autres destinataires.', now(), 'migration-callable-help', now(), 'migration-callable-help', 1),
  ('emailsender.callable.send.bcc', 'es-ES', 'Quién recibe el correo en copia oculta — una o más direcciones, invisibles para los demás destinatarios.', now(), 'migration-callable-help', now(), 'migration-callable-help', 1),
  ('emailsender.callable.send.bcc', 'pt-PT', 'Quem recebe o e-mail em cópia oculta — um ou mais endereços, invisíveis para os outros destinatários.', now(), 'migration-callable-help', now(), 'migration-callable-help', 1),
  ('emailsender.callable.send.variables', 'en-GB', 'The values the template''s placeholders need — each placeholder picks where its value comes from. Suggested keys come from the selected template.', now(), 'migration-callable-help', now(), 'migration-callable-help', 1),
  ('emailsender.callable.send.variables', 'en-US', 'The values the template''s placeholders need — each placeholder picks where its value comes from. Suggested keys come from the selected template.', now(), 'migration-callable-help', now(), 'migration-callable-help', 1),
  ('emailsender.callable.send.variables', 'it-IT', 'I valori di cui hanno bisogno i segnaposto del modello — ogni segnaposto sceglie da dove prendere il suo valore. Le chiavi suggerite arrivano dal modello selezionato.', now(), 'migration-callable-help', now(), 'migration-callable-help', 1),
  ('emailsender.callable.send.variables', 'de-DE', 'Die Werte, die die Platzhalter der Vorlage brauchen — jeder Platzhalter wählt, woher sein Wert kommt. Vorgeschlagene Schlüssel kommen aus der gewählten Vorlage.', now(), 'migration-callable-help', now(), 'migration-callable-help', 1),
  ('emailsender.callable.send.variables', 'fr-FR', 'Les valeurs dont les variables du modèle ont besoin — chaque variable choisit d''où vient sa valeur. Les clés suggérées viennent du modèle sélectionné.', now(), 'migration-callable-help', now(), 'migration-callable-help', 1),
  ('emailsender.callable.send.variables', 'es-ES', 'Los valores que necesitan los marcadores de la plantilla — cada marcador elige de dónde viene su valor. Las claves sugeridas llegan de la plantilla seleccionada.', now(), 'migration-callable-help', now(), 'migration-callable-help', 1),
  ('emailsender.callable.send.variables', 'pt-PT', 'Os valores de que os marcadores do modelo precisam — cada marcador escolhe de onde vem o seu valor. As chaves sugeridas vêm do modelo selecionado.', now(), 'migration-callable-help', now(), 'migration-callable-help', 1)
